// The canonical ingredient dictionary. This is the load-bearing table of the
// whole product: matching is only as good as the collapse from "2 boneless
// skinless chicken thighs, trimmed" to `chicken`.
//
// Each entry: id (also the display name unless `label`), a category that
// drives diet inference, synonyms matched against cleaned ingredient text,
// and flags:
//   staple   default member of the Spicerack (assumed on hand)
//   gluten   contains gluten (drives the weak gluten-free inference)
//   animal   animal-derived even though the category is not obviously so
//            (fish sauce is a condiment; honey is a sweetener)
//
// Categories: meat poultry fish shellfish egg dairy legume grain pasta bread
//             vegetable fruit herb spice oil condiment sweetener nut baking
//             beverage other
//
// Grow this from real query logs and the `unresolved` admin list, not from
// the corpus — the corpus has ten thousand ways to say "salt".

const c = (id, category, synonyms = [], flags = {}) => ({
  id,
  label: flags.label || id.replace(/-/g, " "),
  category,
  synonyms: [id.replace(/-/g, " "), ...synonyms],
  staple: !!flags.staple,
  gluten: !!flags.gluten,
  animal: !!flags.animal,
});

