export const CANONICAL_BY_ID = Object.fromEntries(CANONICALS.map((x) => [x.id, x]));

export const DEFAULT_SPICERACK = CANONICALS.filter((x) => x.staple).map((x) => x.id);

const ANIMAL_CATEGORIES = new Set(["meat", "poultry", "fish", "shellfish", "egg", "dairy"]);
const MEAT_CATEGORIES = new Set(["meat", "poultry"]);
const SEA_CATEGORIES = new Set(["fish", "shellfish"]);

export function isAnimal(id) {
  const x = CANONICAL_BY_ID[id];
  return !!x && (ANIMAL_CATEGORIES.has(x.category) || x.animal);
}
export function isMeat(id) {
  const x = CANONICAL_BY_ID[id];
  return !!x && MEAT_CATEGORIES.has(x.category);
}
export function isSeafood(id) {
  const x = CANONICAL_BY_ID[id];
  return !!x && (SEA_CATEGORIES.has(x.category) || id === "fish-sauce");
}
export function isDairy(id) {
  const x = CANONICAL_BY_ID[id];
  return !!x && x.category === "dairy";
}
export function hasGluten(id) {
  const x = CANONICAL_BY_ID[id];
  return !!x && x.gluten;
}
// Ingredients that carry a meal: used for the "hero" diversity rule so three
// dealt recipes do not all fight over the same pack of chicken.
export function isHero(id) {
  const x = CANONICAL_BY_ID[id];
  return !!x && (ANIMAL_CATEGORIES.has(x.category) && x.category !== "dairy" && x.category !== "egg" || x.category === "legume");
}

/** For autocomplete: [{id, label, category}] sorted by label. */
export const INGREDIENT_OPTIONS = CANONICALS
  .map(({ id, label, category }) => ({ id, label, category }))
  .sort((a, b) => a.label.localeCompare(b.label));
